contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount) public {
        address owner = address(this);
        uint256 balBefore = c.balanceOf(owner); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        require(amount <= balBefore);

        c.burn(amount); if (__ESBMC_reverted()) return;

        assert(c.balanceOf(owner) == balBefore - amount && c.totalSupply() == supplyBefore - amount);
    }
}

