contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 amount) internal {
        address owner = address(this);
        uint256 balBefore;
        try c.balanceOf(owner) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        vm.assume(amount <= balBefore);
        try c.burn(amount) {} catch { return; }
        assertTrue(c.balanceOf(owner) == balBefore - amount && c.totalSupply() == supplyBefore - amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

